import subprocess

from mcp.server.fastmcp import FastMCP

mcp = FastMCP("teamchat-admin")
ALLOWED_ROLES = {"member", "moderator", "admin"}


@mcp.tool()
def set_member_role(workspace_id: str, user_id: str, role: str) -> str:
    if not workspace_id or not user_id:
        return "Error: workspace_id and user_id are required."
    if role not in ALLOWED_ROLES:
        return f"Error: role must be one of {sorted(ALLOWED_ROLES)}."
    result = subprocess.run(
        ["teamchatctl", "roles", "set", "--workspace", workspace_id, "--user", user_id, "--role", role],
        capture_output=True, text=True, timeout=60,
    )
    if result.returncode != 0:
        return f"Error: {result.stderr.strip()}"
    return f"User {user_id} is now {role} in workspace {workspace_id}."
